#!/usr/bin/env bash
set -Eeuo pipefail

STAMP="$(date +%Y%m%d-%H%M%S)"

ROOT="/mnt/SDCARD/data/ports/openmw51"
BIN="$ROOT/bin/openmw-0.51"
MOD="$ROOT/mods/TSPInteriorVisGrid"
LUA="$MOD/scripts/TSPInteriorVisGrid/visgrid.lua"
TOPO="$MOD/scripts/TSPInteriorVisGrid/topology.lua"
OMW="$MOD/TSPInteriorVisGrid.omwscripts"
TOOLS="$HOME/Downloads/visgrid-tools"

PKG="$HOME/Downloads/openmw51-visgrid-v15-navmesh-topology-$STAMP"
LOG="$PKG/install.log"

BASE_V14_SHA="b74f34836ea33093b247bb55157c0748cf3c03373f1b331c53d7a5c99b33b77f"
V15_SHA="2293070930cb4ca8436ca5519d4f1975ebbf62205adeffa47617d46689e61908"
TOPO_SHA="24a6989dacc1149a2a3895da371e56e52d370348d01ea0a5403f4e20755bef6b"
COMPILER_SHA="ac1d2269ae799fb2d2b8adf14db6e31498e1df0bb286c98bfbcc13900f6dd628"
NAV_SOURCE_SHA="2d7037071fa7958bf4e001806a5f08e567682907c14a6769054c3ce49f67e976"

mkdir -p "$PKG/device-backup" "$TOOLS"

if [ -f "$TOOLS/device.env" ]; then
    # shellcheck disable=SC1091
    . "$TOOLS/device.env" || true
fi

if [ -n "${TSP_DEV:-}" ]; then
    DEV="$TSP_DEV"
elif [ -n "${TSP_IP:-}" ]; then
    DEV="root@$TSP_IP"
else
    DEV="root@192.168.1.25"
fi

SSH=(-o BatchMode=yes -o ConnectTimeout=8)
DEPLOY_STARTED=0
REMOTE_BACKUP=""
HAD_TOPO=0
BIN_SHA_BEFORE=""
LIVE_SHA_BEFORE=""

rollback_device() {
    set +e
    [ -n "$REMOTE_BACKUP" ] || return 1
    echo "Attempting automatic V15 device rollback..."
    ssh "${SSH[@]}" "$DEV" "
      set -e
      test -s '$REMOTE_BACKUP/visgrid.lua.before-v15'
      cp -p '$REMOTE_BACKUP/visgrid.lua.before-v15' '$LUA'
      if [ -f '$REMOTE_BACKUP/HAD_TOPOLOGY' ]; then
        test -s '$REMOTE_BACKUP/topology.lua.before-v15'
        cp -p '$REMOTE_BACKUP/topology.lua.before-v15' '$TOPO'
      else
        rm -f '$TOPO'
      fi
      sync
    "
}

fail_report() {
    local rc="${1:-1}" line="${2:-unknown}" cmd="${3:-unknown}"
    trap - ERR
    set +e

    if [ "$DEPLOY_STARTED" = 1 ]; then
        rollback_device || true
    fi

    {
        echo
        echo "=================================================================="
        echo "VISGRID V15 TOPOLOGY PROTOTYPE STOPPED SAFELY"
        echo "=================================================================="
        echo "Date: $(date)"
        echo "Exit code: $rc"
        echo "Line: $line"
        echo "Command: $cmd"
        echo
        [ -f "$LOG" ] && {
            echo "----- install.log tail -----"
            tail -220 "$LOG" || true
        }
        echo
        echo "NO OpenMW source or binary rebuild is performed by this installer."
        echo "Package preserved at:"
        echo "  $PKG"
        [ -n "$REMOTE_BACKUP" ] && echo "Device backup: $REMOTE_BACKUP"
        echo "=================================================================="
    } | tee "$PKG/STOPPED_ERROR.txt"

    exit "$rc"
}
trap 'fail_report "$?" "$LINENO" "$BASH_COMMAND"' ERR
exec > >(tee "$LOG") 2>&1

echo "=================================================================="
echo "OPENMW 0.51 TSP — VISGRID V15 NAVMESH TOPOLOGY PROTOTYPE"
echo "=================================================================="
echo
echo "Prototype scope:"
echo "  Caldera, Governor's Hall only"
echo
echo "V15 contract:"
echo "  topology = structural hint"
echo "  live rays = screen-depth authority"
echo "  mapped doors/stairs = pre-open ray/grace hints"
echo "  panorama/plane cache = per topology sector, not whole cell"
echo "  large/open sectors = no analytic plane-fill shortcut"
echo "  startup/save-load hold = 6.0 seconds"
echo
echo "Unmapped interiors retain V14 fallback behavior."
echo "No C++ rebuild. OpenMW binary remains byte-identical."
echo

command -v ssh >/dev/null
command -v scp >/dev/null
command -v base64 >/dev/null
command -v python3 >/dev/null

echo "===== 1/9 WRITE + VERIFY EXACT V15 ARTIFACTS ====="

