Z2hib3JzPXtzb3J0ZWQoc1snbmVpZ2hib3JzJ10pfSIpCiAgICBwcmludChmInBvcnRhbHM6IHts
ZW4ocG9ydGFscyl9ICh7ZG9vcn0gZG9vciwge3BhdGhncmlkfSBwYXRoZ3JpZCkiKQogICAgcHJp
