KCkK
EOF_COMPILER_B64
base64 -d "$PKG/compile_openmw_navmesh_topology.py.b64" > "$PKG/compile_openmw_navmesh_topology.py"
rm -f "$PKG/compile_openmw_navmesh_topology.py.b64"
chmod +x "$PKG/compile_openmw_navmesh_topology.py"

test "$(sha256sum "$PKG/visgrid-v15.lua" | awk '{print $1}')" = "$V15_SHA"
test "$(sha256sum "$PKG/topology.lua" | awk '{print $1}')" = "$TOPO_SHA"
test "$(sha256sum "$PKG/compile_openmw_navmesh_topology.py" | awk '{print $1}')" = "$COMPILER_SHA"

grep -Fq 'TSP_VISGRID_LUA_V15_TOPOLOGY_BRIDGE' "$PKG/visgrid-v15.lua"
grep -Fq 'TSP_VISGRID_V15_LOADSAFE_6S' "$PKG/visgrid-v15.lua"
grep -Fq 'local POST_LOAD_ARM_DELAY = 6.0' "$PKG/visgrid-v15.lua"
if grep -Fq 'local POST_LOAD_ARM_DELAY = 12.0' "$PKG/visgrid-v15.lua"; then
    echo "ERROR: old 12-second delay survived into V15."
    exit 1
fi
grep -Fq 'TSP_VISGRID_TOPOLOGY_V1' "$PKG/topology.lua"
grep -Fq "$NAV_SOURCE_SHA" "$PKG/topology.lua"
grep -Fq '["Caldera, Governor' "$PKG/topology.lua"

# Syntax parse if any host Lua parser is available.
PARSE_HELPER="$PKG/parsecheck.lua"
cat > "$PARSE_HELPER" <<'EOF_PARSE'
local f=arg[1]
local c,e=loadfile(f)
if not c then error(e) end
print("PARSE PASS " .. f)
EOF_PARSE

if command -v luac >/dev/null 2>&1; then
    luac -p "$PKG/visgrid-v15.lua"
    luac -p "$PKG/topology.lua"
    echo "PASS: Lua parsed with luac."
elif command -v lua >/dev/null 2>&1; then
    lua "$PARSE_HELPER" "$PKG/visgrid-v15.lua"
    lua "$PARSE_HELPER" "$PKG/topology.lua"
    echo "PASS: Lua parsed with lua."
elif command -v luatex >/dev/null 2>&1; then
    luatex --luaonly "$PARSE_HELPER" "$PKG/visgrid-v15.lua"
    luatex --luaonly "$PARSE_HELPER" "$PKG/topology.lua"
    echo "PASS: Lua parsed with luatex."
else
    echo "NOTE: no host Lua parser found; SHA + exact marker verification passed."
fi

echo "Sensor SHA  : $V15_SHA"
echo "Topology SHA: $TOPO_SHA"
echo "Compiler SHA: $COMPILER_SHA"
echo "PASS: exact packaged artifacts verified."

echo
echo "===== 2/9 VERIFY CURRENT DEVICE STATE ====="

if ssh "${SSH[@]}" "$DEV"     'pidof openmw-0.51 >/dev/null 2>&1 || pidof openmw >/dev/null 2>&1'
then
    echo "ERROR: OpenMW is running."
    echo "Exit Morrowind normally, then rerun this SAME installer."
    exit 20
fi

ssh "${SSH[@]}" "$DEV" "
set -e
test -s '$BIN'
test -s '$LUA'
test -s '$OMW'
grep -a -q 'TSP_INTERIOR_VISGRID_051_V1' '$BIN'
grep -Fq 'PLAYER: scripts/TSPInteriorVisGrid/visgrid.lua' '$OMW'
"

BIN_SHA_BEFORE="$(ssh "${SSH[@]}" "$DEV" "sha256sum '$BIN'" | awk '{print $1}')"
LIVE_SHA_BEFORE="$(ssh "${SSH[@]}" "$DEV" "sha256sum '$LUA'" | awk '{print $1}')"

echo "Binary SHA: $BIN_SHA_BEFORE"
echo "Sensor SHA: $LIVE_SHA_BEFORE"

if [ "$LIVE_SHA_BEFORE" = "$BASE_V14_SHA" ]; then
    echo "PASS: exact V14 sensor from topology recon is active."
elif [ "$LIVE_SHA_BEFORE" = "$V15_SHA" ]; then
    echo "PASS: exact V15 sensor already active; rerun-safe refresh."
else
    echo
    echo "ERROR: active sensor is not the exact V14 recon base and is not this V15."
    echo "Expected V14: $BASE_V14_SHA"
    echo "Expected V15: $V15_SHA"
    echo "Found:        $LIVE_SHA_BEFORE"
    echo
    echo "ZERO device changes made."
    echo "This intentionally refuses to overwrite a newer/unknown sensor."
    exit 22
fi

echo
echo "===== 3/9 BACK UP EXACT LIVE DEVICE STATE ====="

REMOTE_BACKUP="$ROOT/backups/visgrid-v15-topology-$STAMP"

ssh "${SSH[@]}" "$DEV" "
set -e
mkdir -p '$REMOTE_BACKUP'
cp -p '$LUA' '$REMOTE_BACKUP/visgrid.lua.before-v15'
cp -p '$OMW' '$REMOTE_BACKUP/TSPInteriorVisGrid.omwscripts.before-v15'
if [ -f '$TOPO' ]; then
    cp -p '$TOPO' '$REMOTE_BACKUP/topology.lua.before-v15'
    : > '$REMOTE_BACKUP/HAD_TOPOLOGY'
fi
sha256sum '$BIN' '$LUA' '$OMW' > '$REMOTE_BACKUP/SHA256SUMS.before.txt'
if [ -f '$TOPO' ]; then sha256sum '$TOPO' >> '$REMOTE_BACKUP/SHA256SUMS.before.txt'; fi
sync
cmp -s '$LUA' '$REMOTE_BACKUP/visgrid.lua.before-v15'
"

if ssh "${SSH[@]}" "$DEV" "test -f '$REMOTE_BACKUP/HAD_TOPOLOGY'"; then
    HAD_TOPO=1
else
    HAD_TOPO=0
fi

scp "${SSH[@]}" -q     "$DEV:$REMOTE_BACKUP/visgrid.lua.before-v15"     "$PKG/device-backup/visgrid.lua.before-v15"
scp "${SSH[@]}" -q     "$DEV:$REMOTE_BACKUP/TSPInteriorVisGrid.omwscripts.before-v15"     "$PKG/device-backup/TSPInteriorVisGrid.omwscripts.before-v15"
scp "${SSH[@]}" -q     "$DEV:$REMOTE_BACKUP/SHA256SUMS.before.txt"     "$PKG/device-backup/SHA256SUMS.before.txt"

test "$(sha256sum "$PKG/device-backup/visgrid.lua.before-v15" | awk '{print $1}')" = "$LIVE_SHA_BEFORE"

if [ "$HAD_TOPO" = 1 ]; then
    scp "${SSH[@]}" -q         "$DEV:$REMOTE_BACKUP/topology.lua.before-v15"         "$PKG/device-backup/topology.lua.before-v15"
fi

echo "PASS: device backup SHA-verified before any deployment."
echo "Device backup: $REMOTE_BACKUP"

echo
echo "===== 4/9 INSTALL STANDALONE COMPILER ON UBUNTU ====="

cp -p "$PKG/compile_openmw_navmesh_topology.py"     "$TOOLS/compile_openmw_navmesh_topology.py"
chmod +x "$TOOLS/compile_openmw_navmesh_topology.py"
test "$(sha256sum "$TOOLS/compile_openmw_navmesh_topology.py" | awk '{print $1}')" = "$COMPILER_SHA"
echo "PASS: compiler available at:"
echo "  $TOOLS/compile_openmw_navmesh_topology.py"

echo
echo "===== 5/9 STAGE TOPOLOGY + SENSOR ON DEVICE ====="

scp "${SSH[@]}" -q "$PKG/topology.lua" "$DEV:/tmp/tsp-topology-v15.lua"
scp "${SSH[@]}" -q "$PKG/visgrid-v15.lua" "$DEV:/tmp/tsp-visgrid-v15.lua"

ssh "${SSH[@]}" "$DEV" "
set -e
sha256sum /tmp/tsp-topology-v15.lua | grep -q '^$TOPO_SHA  '
sha256sum /tmp/tsp-visgrid-v15.lua | grep -q '^$V15_SHA  '
grep -Fq 'TSP_VISGRID_TOPOLOGY_V1' /tmp/tsp-topology-v15.lua
grep -Fq 'TSP_VISGRID_LUA_V15_TOPOLOGY_BRIDGE' /tmp/tsp-visgrid-v15.lua
grep -Fq 'POST_LOAD_ARM_DELAY = 6.0' /tmp/tsp-visgrid-v15.lua
"

echo "PASS: staged bytes verified before replacing live files."

echo
echo "===== 6/9 TRANSACTIONAL DEVICE INSTALL ====="

DEPLOY_STARTED=1

# Install topology first. V14 ignores it if the sensor replacement were to fail.
ssh "${SSH[@]}" "$DEV" "
set -e
mkdir -p '$(dirname "$TOPO")'
cp /tmp/tsp-topology-v15.lua '$TOPO.new'
mv -f '$TOPO.new' '$TOPO'
sync
sha256sum '$TOPO' | grep -q '^$TOPO_SHA  '
"

# Then switch the sensor.
ssh "${SSH[@]}" "$DEV" "
set -e
cp /tmp/tsp-visgrid-v15.lua '$LUA.new'
mv -f '$LUA.new' '$LUA'
rm -f /tmp/tsp-topology-v15.lua /tmp/tsp-visgrid-v15.lua
sync
sha256sum '$LUA' | grep -q '^$V15_SHA  '
"

echo "PASS: topology + V15 sensor installed."

echo
echo "===== 7/9 EXACT POST-INSTALL VERIFY ====="

ssh "${SSH[@]}" "$DEV" "
set -e
sha256sum '$LUA' | grep -q '^$V15_SHA  '
sha256sum '$TOPO' | grep -q '^$TOPO_SHA  '
grep -Fq 'TSP_VISGRID_LUA_V15_TOPOLOGY_BRIDGE' '$LUA'
grep -Fq 'TSP_VISGRID_V15_LOADSAFE_6S' '$LUA'
grep -Fq 'local POST_LOAD_ARM_DELAY = 6.0' '$LUA'
! grep -Fq 'local POST_LOAD_ARM_DELAY = 12.0' '$LUA'
grep -Fq 'TSP_VISGRID_TOPOLOGY_V1' '$TOPO'
grep -Fq '$NAV_SOURCE_SHA' '$TOPO'
grep -Fq 'Caldera, Governor' '$TOPO'
"

BIN_SHA_AFTER="$(ssh "${SSH[@]}" "$DEV" "sha256sum '$BIN'" | awk '{print $1}')"
test "$BIN_SHA_AFTER" = "$BIN_SHA_BEFORE"

echo "PASS: OpenMW binary byte-identical: $BIN_SHA_AFTER"
echo "PASS: V15 sensor + Governor's Hall topology verified."
DEPLOY_STARTED=0

echo
echo "===== 8/9 WRITE FIXED TRACE + ROLLBACK HELPERS ====="

cat > "$TOOLS/pull-visgrid-v15-topology.sh" <<EOF_TRACE
#!/usr/bin/env bash
set -Eeuo pipefail

TOOLS="\$HOME/Downloads/visgrid-tools"
if [ -f "\$TOOLS/device.env" ]; then
  . "\$TOOLS/device.env" || true
fi
if [ -n "\${TSP_DEV:-}" ]; then
  DEV="\$TSP_DEV"
elif [ -n "\${TSP_IP:-}" ]; then
  DEV="root@\$TSP_IP"
else
  DEV="$DEV"
fi
SSH=(-o BatchMode=yes -o ConnectTimeout=8)
STAMP="\$(date +%Y%m%d-%H%M%S)"
OUT="\$HOME/Downloads/visgrid-v15-topology-trace-\$STAMP.txt"

{
  echo "=================================================================="
  echo "VISGRID V15 NAVMESH TOPOLOGY TRACE"
  echo "=================================================================="
  ssh "\${SSH[@]}" "\$DEV" 'date; hostname'

  echo
  echo "===== V15 / V11 / ENGINE ====="
  ssh "\${SSH[@]}" "\$DEV" '
    grep -hE       "TSP_VISGRID_V15|TSP_VISGRID_V11|TSP_INTERIOR_VISGRID|TSP_LOAD_FREEZE|Lua.*ERROR|Lua.*error"       "$ROOT/openmw_051_log.txt" "$ROOT/config-0.51/openmw.log"       2>/dev/null | tail -2600 || true
  '

  echo
  echo "===== PERF ====="
  ssh "\${SSH[@]}" "\$DEV" '
    [ -f "$ROOT/openmw51_perf_latest.txt" ] &&
      tail -500 "$ROOT/openmw51_perf_latest.txt" || true
  '

  echo
  echo "===== INSTALLED STATE ====="
  ssh "\${SSH[@]}" "\$DEV" '
    sha256sum "$BIN" "$LUA" "$TOPO" 2>/dev/null || true
    echo
    grep -nE "TSP_VISGRID_LUA_V15|POST_LOAD_ARM_DELAY|TSP_VISGRID_TOPOLOGY_V1"       "$LUA" "$TOPO" 2>/dev/null | head -80 || true
  '
} 2>&1 | tee "\$OUT"

echo
echo "Saved:"
echo "  \$OUT"
EOF_TRACE
chmod +x "$TOOLS/pull-visgrid-v15-topology.sh"

cat > "$TOOLS/rollback-visgrid-v15-topology.sh" <<EOF_ROLL
#!/usr/bin/env bash
set -Eeuo pipefail

TOOLS="\$HOME/Downloads/visgrid-tools"
if [ -f "\$TOOLS/device.env" ]; then
  . "\$TOOLS/device.env" || true
fi
if [ -n "\${TSP_DEV:-}" ]; then
  DEV="\$TSP_DEV"
elif [ -n "\${TSP_IP:-}" ]; then
  DEV="root@\$TSP_IP"
else
  DEV="$DEV"
fi
SSH=(-o BatchMode=yes -o ConnectTimeout=8)
LUA="$LUA"
TOPO="$TOPO"
BACKUP="$REMOTE_BACKUP"

if ssh "\${SSH[@]}" "\$DEV"   'pidof openmw-0.51 >/dev/null 2>&1 || pidof openmw >/dev/null 2>&1'
then
  echo "ERROR: exit OpenMW before rollback."
  exit 20
fi

ssh "\${SSH[@]}" "\$DEV" "
set -e
test -s '\$BACKUP/visgrid.lua.before-v15'
cp -p '\$BACKUP/visgrid.lua.before-v15' '\$LUA'
if [ -f '\$BACKUP/HAD_TOPOLOGY' ]; then
  test -s '\$BACKUP/topology.lua.before-v15'
  cp -p '\$BACKUP/topology.lua.before-v15' '\$TOPO'
else
  rm -f '\$TOPO'
fi
sync
sha256sum '\$LUA'
[ ! -f '\$TOPO' ] || sha256sum '\$TOPO'
"
echo "PASS: exact pre-V15 sensor/topology state restored."
EOF_ROLL
chmod +x "$TOOLS/rollback-visgrid-v15-topology.sh"

cp -p "$TOOLS/pull-visgrid-v15-topology.sh" "$PKG/"
cp -p "$TOOLS/rollback-visgrid-v15-topology.sh" "$PKG/"

echo "PASS: fixed tools installed:"
echo "  $TOOLS/pull-visgrid-v15-topology.sh"
echo "  $TOOLS/rollback-visgrid-v15-topology.sh"

echo
echo "===== 9/9 WRITE README ====="

cat > "$PKG/README-V15.txt" <<EOF_README
VISGRID V15 NAVMESH TOPOLOGY PROTOTYPE
=======================================

Source live navmesh SHA256:
  $NAV_SOURCE_SHA

Captured live navmesh:
  10 Detour tiles
  427 walkable ground polygons
  4 strong walkable Z bands:
    approximately -119, 136, 391, 646 world Z
  38 conservative structural sectors
  3 explicit Detour door portals
  structural stair/vertical-connector boundary portals

V15 runtime contract:
  - Governor's Hall topology is a structural hint, NEVER a tile-depth clamp.
  - Live World+Door rays remain the screen-depth correctness authority.
  - Learned panorama/wall planes are cached per topology sector.
  - Crossing floors/rooms does not carry the previous sector's full stale
    panorama into the new sector.
  - Approaching mapped doors or staircase/vertical connectors briefly opens
    only that angular region and raises its ray priority.
  - large_open sectors skip analytic plane-fill so open chambers are not
    prematurely collapsed by inferred walls.
  - existing live door-state watcher remains active.
  - old V14 scalar map/Z behavior remains unchanged in UNMAPPED interiors.
  - post-load/start activation hold is 6.0 seconds.
  - first post-load frame still explicitly disarms stale engine grid state.

This prototype DOES NOT YET perform direct C++ object-sector/PVS rejection.
That is the next stage after the sector IDs and portal transitions prove stable.

Trace while OpenMW is still running:
  ~/Downloads/visgrid-tools/pull-visgrid-v15-topology.sh

Rollback with OpenMW closed:
  ~/Downloads/visgrid-tools/rollback-visgrid-v15-topology.sh

Future compiler:
  ~/Downloads/visgrid-tools/compile_openmw_navmesh_topology.py
EOF_README

echo "=================================================================="
echo "V15 NAVMESH TOPOLOGY PROTOTYPE INSTALLED"
echo "=================================================================="
echo
echo "IMPORTANT:"
echo "  The cooldown is now 6.0 seconds, not 12."
echo "  The same first-frame safeDisarm/load-safety sequence is preserved."
echo
echo "Test in Governor's Hall:"
echo "  1. Load the normal benchmark save."
echo "  2. Wait through the 6-second hold."
echo "  3. Bad wall / stand still."
echo "  4. Walk while keeping wall in view."
echo "  5. Enter/leave small rooms."
echo "  6. Approach/open doors."
echo "  7. Walk staircases between floors."
echo "  8. Look across the large/open room."
echo
echo "Watch for these new fields:"
echo "  topo=1"
echo "  sect=<id>"
echo "  floor=<id>"
echo "  kind=large_open|room|small_room|corridor|vertical_connector"
echo "  ph=<portal hints>"
echo "  sw=<sector switches>"
echo
echo "While OpenMW is still running:"
echo "  ~/Downloads/visgrid-tools/pull-visgrid-v15-topology.sh"
echo
echo "Rollback:"
echo "  ~/Downloads/visgrid-tools/rollback-visgrid-v15-topology.sh"
echo
echo "Package:"
echo "  $PKG"
echo "=================================================================="
